  {"id":"vasculitis-prs-1","topic":"Vasculitis: pulmonary-renal syndrome","domain":"Internal medicine: rheumatology, immunology & allergy (gout & crystal arthropathy, SLE, RA, vasculitides, anaphylaxis & angioedema, drug reactions)","discipline":"medicine","stem":"Name the three ANCA-associated vasculitides classified at the 2012 Chapel Hill Consensus.","answer":"Granulomatosis with polyangiitis (GPA), microscopic polyangiitis (MPA), and eosinophilic granulomatosis with polyangiitis (EGPA/Churg-Strauss).","rationale":"All three are small-vessel vasculitides linked to ANCA; GPA features necrotizing granulomas affecting upper/lower airway and kidneys.","bloom":"recall","source":[{"book":"StatPearls: StatPearls   Granulomatosis with polyangiitis (GPA Wegener)","page":2}],"confusable_with":"Polyarteritis nodosa (medium vessel, ANCA-negative)"},
  {"id":"vasculitis-prs-2","topic":"Vasculitis: pulmonary-renal syndrome","domain":"Internal medicine: rheumatology, immunology & allergy (gout & crystal arthropathy, SLE, RA, vasculitides, anaphylaxis & angioedema, drug reactions)","discipline":"medicine","stem":"Match vessel size to clinical manifestations for vasculitis: large, medium, and small vessel disease.","answer":"Large vessel: limb claudication, bruits, asymmetric BP, vision loss. Medium vessel: digital gangrene, mononeuritis multiplex, renovascular HTN. Small vessel: palpable purpura, glomerulonephritis, small airway disease.","rationale":"Vessel size determines organ territory affected; recognizing the pattern guides the diagnostic workup and biopsy site.","bloom":"analyze","source":[{"book":"MGH Housestaff Manual","page":176}],"confusable_with":""},
  {"id":"vasculitis-prs-3","topic":"Vasculitis: pulmonary-renal syndrome","domain":"Internal medicine: rheumatology, immunology & allergy (gout & crystal arthropathy, SLE, RA, vasculitides, anaphylaxis & angioedema, drug reactions)","discipline":"medicine","stem":"What is the gold standard for diagnosing vasculitis and what histologic findings confirm it?","answer":"Tissue biopsy; shows inflammatory infiltrates of vessel wall with fibrinoid necrosis (and absence of granulomas in PAN).","rationale":"Imaging can suggest vasculitis but histology confirms diagnosis and guides treatment intensity.","bloom":"recall","source":[{"book":"MGH Housestaff Manual","page":177}],"confusable_with":"GPA (positive granulomas on biopsy)"},
  {"id":"vasculitis-prs-4","topic":"Vasculitis: pulmonary-renal syndrome","domain":"Internal medicine: rheumatology, immunology & allergy (gout & crystal arthropathy, SLE, RA, vasculitides, anaphylaxis & angioedema, drug reactions)","discipline":"medicine","stem":"What induction treatment is used for severe ANCA-associated vasculitis?","answer":"IV corticosteroids + cyclophosphamide for severe disease; prednisone 1mg/kg/d +/- MTX or AZA for moderate disease.","rationale":"Rapid immunosuppression halts organ-threatening vasculitis; cyclophosphamide reserved for severe cases due to toxicity.","bloom":"apply","source":[{"book":"MGH Housestaff Manual","page":177}],"confusable_with":""},
  {"id":"vasculitis-prs-5","topic":"Vasculitis: pulmonary-renal syndrome","domain":"Internal medicine: rheumatology, immunology & allergy (gout & crystal arthropathy, SLE, RA, vasculitides, anaphylaxis & angioedema, drug reactions)","discipline":"medicine","stem":"What skin finding is most specific for small vessel vasculitis?","answer":"Palpable purpura (non-blanching, raised petechiae); reflects immune-mediated inflammation of small dermal vessels.","rationale":"Palpable purpura distinguishes vasculitis from thrombocytopenic petechiae (flat, blanching) by vessel wall inflammation.","bloom":"recall","source":[{"book":"MGH Housestaff Manual","page":176}],"confusable_with":"Thrombocytopenic petechiae (flat, non-palpable)"}
