  {"id":"vte-icu-2","topic":"Venous Thromboembolism in ICU","domain":"Internal medicine: ICU & critical care (all-cause shock, vasopressors & inotropes, invasive & noninvasive ventilation, sedation & analgesia, multiorgan failure, rapid response, ACLS)","discipline":"medicine","stem":"When is mechanical VTE prophylaxis (compression stockings, IPC) preferred over chemoprophylaxis in the ICU?","answer":"When chemoprophylaxis bleeding risk is high; mechanical prophylaxis provides some protection but is less effective than chemical.","rationale":"Mechanical prophylaxis reduces VTE without bleeding risk but is generally ineffective as dual therapy in patients already receiving chemoprophylaxis.","bloom":"apply","source":[{"book":"Miller/Baby Miller","page":773}],"confusable_with":""},
  {"id":"vte-icu-3","topic":"Venous Thromboembolism in ICU","domain":"Internal medicine: ICU & critical care (all-cause shock, vasopressors & inotropes, invasive & noninvasive ventilation, sedation & analgesia, multiorgan failure, rapid response, ACLS)","discipline":"medicine","stem":"Delirium affects up to what percentage of mechanically ventilated ICU patients and what are its long-term consequences?","answer":"Up to 80% of mechanically ventilated patients; associated with increased mortality, prolonged ICU stay, and long-term cognitive impairment.","rationale":"ICU delirium is underrecognized and preventable; sedation minimization, early mobility, and sleep hygiene are key prevention strategies.","bloom":"recall","source":[{"book":"Miller/Baby Miller","page":775}],"confusable_with":""},
  {"id":"vte-icu-4","topic":"Venous Thromboembolism in ICU","domain":"Internal medicine: ICU & critical care (all-cause shock, vasopressors & inotropes, invasive & noninvasive ventilation, sedation & analgesia, multiorgan failure, rapid response, ACLS)","discipline":"medicine","stem":"What two patient conditions increase risk of gastrointestinal stress ulcer bleeding in the ICU?","answer":"Mechanical ventilation >48 hours and coagulopathy are the major risk factors for ICU GI stress ulcer bleeding.","rationale":"Increased gastric acid production plus impaired mucosal barrier in critical illness causes stress ulcers; these conditions shift the balance toward bleeding.","bloom":"recall","source":[{"book":"Miller/Baby Miller","page":773}],"confusable_with":""}
